def build_model():
    p=PARAMETERS; wires=[]
    for sec in p["sections"]:
        plane=cq.Plane(origin=tuple(p["origin"][i]+p["normal"][i]*sec["z"] for i in range(3)), xDir=tuple(p["xdir"]), normal=tuple(p["normal"]))
        wires.append(cq.Workplane(plane).spline([tuple(x) for x in sec["points"]], periodic=False).close().val())
    return cq.Solid.makeLoft(wires, True)

if __name__ == "__main__":
    out=Path(__file__).resolve().parent; t=time.time(); shape=build_model(); valid=bool(shape.isValid())
    cq.exporters.export(shape,str(out/"reconstructed.step")); cq.exporters.export(shape,str(out/"reconstructed.stl"))
    b=shape.BoundingBox(); (out/"geometry.json").write_text(json.dumps(dict(valid=valid,solids=len(shape.Solids()),faces=len(shape.Faces()),bbox=[b.xmin,b.ymin,b.zmin,b.xmax,b.ymax,b.zmax],build_seconds=time.time()-t),indent=2))
    print("VALIDATED",valid,"SOLIDS",len(shape.Solids()),"FACES",len(shape.Faces()),flush=True)
